<script setup>
import { computed, reactive, ref, watch, nextTick } from 'vue'
import { ElTable, ElTableColumn, ElTag } from 'element-plus'
import { state, rebate, largestMarketId, grant, editProduct, saveCompany, reset } from '../../shared/store.js'
import { money } from '../../shared/demo.mjs'
import { createRequestId } from '../../shared/request-id.mjs'
import Icon from '../../shared/Icon.vue'
const menus = [
  { id: 'overview', title: '运营概览', icon: 'grid', subtitle: '掌握商城的每一份日常' },
  { id: 'products', title: '商品管理', icon: 'bag', subtitle: '管理商品资料与上架状态' },
  { id: 'orders', title: '订单管理', icon: 'orders', subtitle: '查询购买记录与线下收货信息' },
  { id: 'users', title: '用户管理', icon: 'team', subtitle: '查看用户、上下线与产品券信息' },
  { id: 'grants', title: '产品券发放', icon: 'ticket', subtitle: '为用户发放产品券，记录每一笔变动' },
  { id: 'rebates', title: '团队与返利', icon: 'chart', subtitle: '累计市场消费与返利发放记录' },
  { id: 'company', title: '公司介绍', icon: 'home', subtitle: '编辑手机首页展示内容' },
  { id: 'jobs', title: '结算与对账', icon: 'clock', subtitle: '每日补查与账务一致性' }
]
const active = ref('overview'), search = ref(''), selectedOrder = ref(null), editing = ref(null), error = ref(''), notice = ref('')
const adminDialog = ref(null)
watch([editing, selectedOrder], async () => { await nextTick(); if (adminDialog.value && !adminDialog.value.open) adminDialog.value.showModal() })
const title = computed(() => menus.find(m => m.id === active.value))
const orders = computed(() => state.value.orders.filter(o => `${o.id}${o.product.name}`.includes(search.value.trim())))
const totalSpend = computed(() => state.value.orders.reduce((s, o) => s + o.totalUnits, 0))
const company = reactive({ ...state.value.company }), productForm = reactive({ name: '', subtitle: '', price: '', description: '', active: true })
const grantForm = reactive({ amount: '', note: '' })
const grantHistory = computed(() => state.value.ledger.filter(i => i.type === 'grant'))
function go(id) { active.value = id; search.value = ''; notice.value = ''; error.value = '' }
function perform(action, text) { error.value = ''; notice.value = ''; try { action(); notice.value = text } catch (e) { error.value = e.message } }
function issue() { perform(() => {
  if (!/^\d+(\.\d{1,2})?$/.test(grantForm.amount)) throw new Error('请输入最多两位小数的正数券数')
  if (!grantForm.note.trim()) throw new Error('请填写发放备注')
  grant(Math.round(Number(grantForm.amount) * 100), grantForm.note, createRequestId())
  grantForm.amount = ''; grantForm.note = ''
}, '演示产品券已发放，可在用户端查看余额与流水。') }
function openProduct(p) { editing.value = p.id; Object.assign(productForm, { name: p.name, subtitle: p.subtitle, price: (p.priceUnits / 100).toFixed(2), description: p.description, active: p.active }); error.value = '' }
function submitProduct() { perform(() => {
  if (!/^\d+(\.\d{1,2})?$/.test(productForm.price)) throw new Error('请输入有效产品券价格')
  editProduct(editing.value, { name: productForm.name, subtitle: productForm.subtitle, priceUnits: Math.round(Number(productForm.price) * 100), description: productForm.description, active: productForm.active })
  editing.value = null
}, '商品演示资料已保存。') }
function resetDemo() { if (window.confirm('重置全部演示数据？演示购买和发券记录将被清除。')) perform(() => { reset(); Object.assign(company, state.value.company) }, '演示数据已重置。') }
</script>
<template>
  <div class="admin-shell">
    <aside class="sidebar"><div class="admin-brand"><span>券</span><div>产品券商城<small>MANAGEMENT CONSOLE</small></div></div><div class="side-section-label">工作空间</div><nav aria-label="后台菜单"><button v-for="item in menus" :key="item.id" :class="{ active: active === item.id }" @click="go(item.id)"><Icon :name="item.icon" :size="19" />{{ item.title }}<span v-if="active === item.id" class="active-dot"></span></button></nav><div class="sidebar-bottom"><Icon name="shield" :size="20" /><div>简单运营，清晰记录<small>产品券商城管理系统</small></div></div></aside>
    <div class="admin-main"><header class="admin-topbar"><span>管理后台 <span class="breadcrumb">/ {{ title.title }}</span></span><div><span class="demo-badge"><i></i>界面预览 · 演示数据</span><span class="admin-avatar">管</span><span class="admin-name">管理员</span></div></header>
      <main class="admin-content"><div class="admin-page-heading"><div><span class="admin-eyebrow">WORKSPACE / {{ active.toUpperCase() }}</span><h1>{{ title.title }}</h1><p>{{ title.subtitle }}</p></div><button class="secondary" @click="resetDemo"><Icon name="settings" :size="15" />重置演示</button></div>
        <p v-if="notice" class="admin-success" role="status"><Icon name="check" :size="17" />{{ notice }}</p><p v-if="error" class="error" role="alert">{{ error }}</p>
        <template v-if="active === 'overview'">
          <section class="welcome-banner"><div><span>把品质带进日常，把运营做得简单。</span><h2>每一份产品券，都有清晰的去向</h2><p>从商品购买到团队返利，在这里查看商城记录。</p></div><Icon name="ticket" :size="96" /></section>
          <div class="stats-grid"><div class="stat-card"><span class="stat-icon blue"><Icon name="orders" /></span><span>购买订单</span><strong>{{ state.orders.length }}<small>笔</small></strong><p>当前演示账号购买记录</p></div><div class="stat-card"><span class="stat-icon gold"><Icon name="ticket" /></span><span>累计消耗产品券</span><strong>{{ money(totalSpend) }}<small>券</small></strong><p>以成功购买金额统计</p></div><div class="stat-card"><span class="stat-icon green"><Icon name="chart" /></span><span>累计已发返利</span><strong>{{ money(state.paidRebateUnits) }}<small>券</small></strong><p>演示团队返利累计</p></div><div class="stat-card"><span class="stat-icon blue"><Icon name="bag" /></span><span>在售商品</span><strong>{{ state.products.filter(p => p.active).length }}<small>件</small></strong><p>已上架可购买商品</p></div></div>
          <section class="panel"><div class="panel-heading"><div><h2>最近购买</h2><p>每一笔成功下单的购买记录</p></div><button class="text-link" @click="go('orders')">全部订单 <Icon name="arrow" :size="15" /></button></div><ElTable :data="state.orders.slice(0, 5)" empty-text="暂无订单"><ElTableColumn prop="id" label="订单编号" min-width="190"/><ElTableColumn prop="product.name" label="商品" min-width="160"/><ElTableColumn label="产品券消耗" min-width="130"><template #default="{ row }"><b>{{ money(row.totalUnits) }} 券</b></template></ElTableColumn><ElTableColumn prop="createdAt" label="购买时间" min-width="180"/><ElTableColumn label="购买结果" width="100"><template #default><ElTag type="success" effect="plain">购买成功</ElTag></template></ElTableColumn></ElTable></section>
          <div class="overview-bottom"><section class="panel"><div class="panel-heading"><h2>常用操作</h2></div><div class="quick-actions"><button v-for="item in [menus[1], menus[4], menus[6]]" :key="item.id" @click="go(item.id)"><Icon :name="item.icon" :size="24" /><span>{{ item.title }}</span><Icon name="arrow" :size="16" /></button></div></section><section class="panel rule-panel"><span class="admin-eyebrow">REBATE RULE</span><h2>累计差额返利 · 10%</h2><p>排除累计消费最大的一个子市场，其余子市场累计消费 × 10%，减去已发返利后补发差额。</p><span class="rule-foot"><Icon name="clock" :size="15" />消费变动重算 + 每日定时补查</span></section></div>
        </template>
        <section v-if="active === 'products'" class="panel"><div class="panel-heading"><div><h2>商品列表</h2><p>演示编辑、上下架会同步到同浏览器手机预览</p></div><span class="muted">{{ state.products.length }} 件商品</span></div><ElTable :data="state.products"><ElTableColumn label="商品信息" min-width="240"><template #default="{ row }"><div class="admin-product"><img :src="row.image" :alt="row.name"><span><strong>{{ row.name }}</strong><small>{{ row.subtitle }}</small></span></div></template></ElTableColumn><ElTableColumn label="售价" min-width="130"><template #default="{ row }">{{ money(row.priceUnits) }} 券</template></ElTableColumn><ElTableColumn label="状态" width="110"><template #default="{ row }"><ElTag :type="row.active ? 'success' : 'info'" effect="plain">{{ row.active ? '已上架' : '已下架' }}</ElTag></template></ElTableColumn><ElTableColumn label="操作" width="170"><template #default="{ row }"><button class="table-button" @click="openProduct(row)">编辑</button><button class="table-button" @click="perform(() => editProduct(row.id, { ...row, active: !row.active }), '上架状态已更新。')">{{ row.active ? '下架' : '上架' }}</button></template></ElTableColumn></ElTable><p class="state-note panel-note">此阶段可编辑现有演示商品；创建商品及图片管理在正式后台接入时提供。</p></section>
        <section v-if="active === 'orders'" class="panel"><div class="panel-heading"><div><h2>购买记录</h2><p>仅记录购买结果，不设置线上物流状态</p></div><label class="admin-search"><Icon name="search" :size="17"/><input v-model="search" aria-label="搜索订单" placeholder="订单号 / 商品名称"></label></div><ElTable :data="orders" empty-text="没有匹配的订单"><ElTableColumn prop="id" label="订单编号" min-width="200"/><ElTableColumn prop="product.name" label="商品名称" min-width="160"/><ElTableColumn prop="quantity" label="数量" width="80"/><ElTableColumn label="消耗产品券" min-width="130"><template #default="{ row }">{{ money(row.totalUnits) }} 券</template></ElTableColumn><ElTableColumn prop="createdAt" label="购买时间" min-width="180"/><ElTableColumn label="操作" width="90"><template #default="{ row }"><button class="table-button" @click="selectedOrder = row">查看详情</button></template></ElTableColumn></ElTable></section>
        <section v-if="active === 'users'" class="panel"><div class="panel-heading"><div><h2>用户列表</h2><p>当前仅展示可交互的演示账号</p></div></div><ElTable :data="[{ ...state.profile, balanceUnits: state.balanceUnits }]" ><ElTableColumn prop="id" label="用户 ID" min-width="120"/><ElTableColumn prop="nickname" label="昵称" min-width="130"/><ElTableColumn prop="inviteCode" label="邀请码" min-width="120"/><ElTableColumn label="产品券余额" min-width="160"><template #default="{ row }">{{ money(row.balanceUnits) }} 券</template></ElTableColumn><ElTableColumn label="直属下线" width="100"><template #default>{{ state.markets.length }} 人</template></ElTableColumn><ElTableColumn label="操作" width="100"><template #default><button class="table-button" @click="go('grants')">发放产品券</button></template></ElTableColumn></ElTable><p class="state-note panel-note">上下线绑定后用户不可更换。开发者维护关系需按数据库维护方案执行，不提供日常修改按钮。</p></section>
        <template v-if="active === 'grants'"><div class="form-layout"><section class="panel"><div class="panel-heading"><h2>发放产品券</h2></div><form class="form-stack" @submit.prevent="issue"><label>发放用户<input :value="`${state.profile.nickname} · ID ${state.profile.id}`" readonly></label><label>发放数量 / 券<input v-model="grantForm.amount" inputmode="decimal" placeholder="请输入正数，最多两位小数" required></label><label>发放备注<textarea v-model="grantForm.note" rows="3" placeholder="填写本次发放原因" required maxlength="200"></textarea></label><button class="primary" type="submit"><Icon name="plus" :size="17" />确认演示发放</button></form></section><section class="panel guidance-panel"><span class="stat-icon gold"><Icon name="ticket" :size="27" /></span><h2>每笔发放，都留有记录</h2><p>发放成功后，用户产品券余额增加，并产生相应的收支明细。</p><dl><div><dt>当前用户余额</dt><dd>{{ money(state.balanceUnits) }} 券</dd></div><div><dt>使用范围</dt><dd>商城商品购买</dd></div><div><dt>交易方式</dt><dd>不涉及线上现金交易</dd></div></dl></section></div><section class="panel"><div class="panel-heading"><h2>发放记录</h2></div><ElTable :data="grantHistory"><ElTableColumn prop="createdAt" label="发放时间" min-width="180"/><ElTableColumn label="数量" min-width="130"><template #default="{ row }">+{{ money(row.amountUnits) }} 券</template></ElTableColumn><ElTableColumn prop="note" label="发放备注" min-width="240"/></ElTable></section></template>
        <template v-if="active === 'rebates'"><div class="stats-grid three"><div v-for="s in [{ label: '团队累计消费', value: rebate.total }, { label: '累计应得返利', value: rebate.entitled }, { label: '累计已发返利', value: rebate.paid }]" :key="s.label" class="stat-card"><span>{{ s.label }}</span><strong>{{ money(s.value) }}<small>券</small></strong></div></div><section class="panel"><div class="panel-heading"><div><h2>{{ state.profile.nickname }}的子市场</h2><p>每个直属下线及其所有下级构成一个市场</p></div></div><ElTable :data="state.markets"><ElTableColumn prop="id" label="直属用户 ID" min-width="130"/><ElTableColumn prop="name" label="直属下线" min-width="130"/><ElTableColumn prop="members" label="团队人数" min-width="100"/><ElTableColumn label="累计消费" min-width="150"><template #default="{ row }">{{ money(row.units) }} 券</template></ElTableColumn><ElTableColumn label="计奖口径" min-width="140"><template #default="{ row }"><ElTag :type="row.id === largestMarketId ? 'warning' : 'success'" effect="plain">{{ row.id === largestMarketId ? '最大市场 · 排除' : '参与计奖' }}</ElTag></template></ElTableColumn></ElTable><p class="state-note panel-note">累计应得 =（{{ money(rebate.total) }} − {{ money(rebate.largest) }}）× 10% = {{ money(rebate.entitled) }} 券。此处展示固定演示团队，尚未接入真实多级结算。</p></section></template>
        <section v-if="active === 'company'" class="panel content-editor"><div class="panel-heading"><h2>首页展示内容</h2></div><form class="form-stack" @submit.prevent="perform(() => saveCompany({ ...company }), '公司介绍已保存到本地演示，可在手机首页查看。')"><label>商城名称<input v-model="company.name" required maxlength="20"></label><label>品牌主标题<input v-model="company.tagline" required maxlength="20"></label><label>公司简介<textarea v-model="company.intro" rows="4" required maxlength="500"></textarea></label><label>品牌理念<textarea v-model="company.body" rows="5" maxlength="1000"></textarea></label><button class="primary" type="submit">保存演示内容</button></form></section>
        <section v-if="active === 'jobs'" class="panel pending-panel"><span class="pending-icon"><Icon name="clock" :size="38" /></span><h2>结算与对账将在后端阶段接入</h2><p>计划每天北京时间 02:00 补查，消费发生时立即重算。<br>以累计应得与已发差额补发，避免重复入账。</p><div class="pending-rules"><span><Icon name="check" :size="17" />累计最大市场排除</span><span><Icon name="check" :size="17" />10% 产品券返利</span><span><Icon name="check" :size="17" />订单与流水一致性校验</span></div><p class="state-note">当前没有真实调度器、任务执行记录或后端认证。请勿将界面预览作为生产系统使用。</p></section>
        <footer class="admin-footer">产品券商城管理后台<span>界面预览版本 · 本地演示</span></footer>
      </main>
    </div>
    <dialog v-if="editing || selectedOrder" ref="adminDialog" class="admin-dialog" aria-labelledby="admin-dialog-title" @cancel.prevent="editing = null; selectedOrder = null"><div class="panel-heading"><h2 id="admin-dialog-title">{{ editing ? '编辑商品' : '订单详情' }}</h2><button class="icon-btn" aria-label="关闭" @click="editing = null; selectedOrder = null"><Icon name="close" /></button></div><form v-if="editing" class="form-stack" @submit.prevent="submitProduct"><label>商品名称<input v-model="productForm.name" required maxlength="60"></label><label>规格说明<input v-model="productForm.subtitle" maxlength="80"></label><label>产品券价格<input v-model="productForm.price" inputmode="decimal" required></label><label>商品说明<textarea v-model="productForm.description" rows="4" maxlength="1000"></textarea></label><p v-if="error" class="error" role="alert">{{ error }}</p><button class="primary" type="submit">保存商品</button></form><template v-if="selectedOrder"><div class="admin-product dialog-product"><img :src="selectedOrder.product.image" :alt="selectedOrder.product.name"><span><strong>{{ selectedOrder.product.name }}</strong><small>{{ selectedOrder.product.subtitle }} × {{ selectedOrder.quantity }}</small></span></div><dl class="order-detail-list"><div><dt>订单编号</dt><dd>{{ selectedOrder.id }}</dd></div><div><dt>购买时间</dt><dd>{{ selectedOrder.createdAt }}</dd></div><div><dt>消耗产品券</dt><dd>{{ money(selectedOrder.totalUnits) }} 券</dd></div><div><dt>收件人</dt><dd>{{ selectedOrder.address.recipient }} · {{ selectedOrder.address.phone }}</dd></div><div><dt>下单地址</dt><dd>{{ selectedOrder.address.detail }}</dd></div></dl><p class="state-note">保留下单时收货信息，商品由线下安排发货。</p></template></dialog>
  </div>
</template>
